#pragma GCC optimize(3)
#include <bits/stdc++.h>
#define MAX_SIZE 7100
typedef long long ll;
#define INF 1000000000
using namespace std;

struct MaxFlow {
    struct Edge {
        int from, to;
        ll flow, capacity;
    };

    int start, end_point;
    vector<Edge> edges;
    vector<int> graph[MAX_SIZE];
    int distance[MAX_SIZE], visited[MAX_SIZE], current[MAX_SIZE];

    void initialize() {
        edges.clear();
        for (int i = 0; i < MAX_SIZE; i++) {
            graph[i].clear();
        }
    }

    void add_edge(int from, int to, ll cap) {
        Edge e1 = {from, to, 0LL, cap};
        Edge e2 = {to, from, 0LL, 0LL};
        edges.push_back(e1);
        edges.push_back(e2);
        graph[from].push_back((int)edges.size() - 2);
        graph[to].push_back((int)edges.size() - 1);
    }

    bool build_level_graph() {
        memset(visited, 0, sizeof(visited));
        memset(distance, 0, sizeof(distance));
        queue<int> q;
        q.push(start);
        visited[start] = 1;
        distance[start] = 0;
        while (!q.empty()) {
            int v = q.front(); q.pop();
            for (int i = 0; i < (int)graph[v].size(); i++) {
                Edge &e = edges[graph[v][i]];
                int nxt = e.to;
                if (!visited[nxt] && e.capacity > e.flow) {
                    distance[nxt] = distance[v] + 1;
                    q.push(nxt);
                    visited[nxt] = 1;
                }
            }
        }
        return visited[end_point];
    }

    ll send_flow(int v, ll flow) {
        if (v == end_point || flow == 0) return flow;
        ll total_flow = 0;
        for (int &i = current[v]; i < (int)graph[v].size(); i++) {
            Edge &e = edges[graph[v][i]];
            if (distance[v] + 1 == distance[e.to]) {
                ll min_cap = min(flow, e.capacity - e.flow);
                ll pushed = send_flow(e.to, min_cap);
                if (pushed > 0) {
                    e.flow += pushed;
                    edges[graph[v][i] ^ 1].flow -= pushed;
                    total_flow += pushed;
                    flow -= pushed;
                    if (flow == 0) break;
                }
            }
        }
        return total_flow;
    }

    ll max_flow() {
        ll total = 0;
        while (build_level_graph()) {
            for (int i = 0; i < MAX_SIZE; i++) current[i] = 0;
            total += send_flow(start, INF);
        }
        return total;
    }
};

MaxFlow mf;
char grid1[14][14], grid2[14][14];
bool visited_cells[14][14];
int dist_cells[14][14];
int n;
int target[103];

void BFS(int x, int y) {
    std::queue<std::pair<std::pair<int, int>, int>> q;
    for (int i = 0; i < 14; i++) {
        for (int j = 0; j < 14; j++) {
            dist_cells[i][j] = 111;
        }
    }
    dist_cells[x][y] = 0;
    q.push({{x, y}, 0});
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    while (!q.empty()) {
        auto p = q.front(); q.pop();
        int cx = p.first.first, cy = p.first.second, d = p.second;
        if (visited_cells[cx][cy]) continue;
        visited_cells[cx][cy] = true;
        dist_cells[cx][cy] = d;
        for (int i = 0; i < 4; i++) {
            int tx = cx + dx[i], ty = cy + dy[i];
            if (tx <= 0 || tx > n || ty <= 0 || ty > n || visited_cells[tx][ty] || grid1[tx][ty] == 'Y') continue;
            q.push({{tx, ty}, d + 1});
        }
    }
}

int get_index(int level, int x, int y) {
    return level * n * n + (x - 1) * n + y;
}

int main() {
    int i, t, j, k;
    scanf("%d%d", &n, &t);
    for (i = 1; i <= n; i++) scanf("%s", grid1[i] + 1);
    for (i = 1; i <= n; i++) scanf("%s", grid2[i] + 1);
    mf.start = 0; mf.end_point = MAX_SIZE - 2;
    int x = 0, y = 0;
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (grid1[i][j] == 'Z') {
                x = i; y = j; break;
            }
        }
    }
    for (i = 1; i <= n * n; i++) target[i] = MAX_SIZE - 3 - (n * n - i);
    BFS(x, y);
    for (i = 1; i <= n; i++) {
        for (j = 1; j <= n; j++) {
            if (grid1[i][j] >= '0' && grid1[i][j] <= '9')
                mf.add_edge(mf.start, get_index(0, i, j), grid1[i][j] - '0');
            if (grid2[i][j] >= '0' && grid2[i][j] <= '9')
                mf.add_edge(target[get_index(0, i, j)], mf.end_point, grid2[i][j] - '0');
            mf.add_edge(get_index(0, i, j), target[get_index(0, i, j)], INF);
        }
    }
    int dx[4] = {1, 0, 0, -1}, dy[4] = {0, 1, -1, 0};
    for (i = 1; i <= t; i++) {
        for (j = 1; j <= n; j++) {
            for (k = 1; k <= n; k++) {
                if (grid1[j][k] == 'Y' || grid1[j][k] == 'Z') continue;
                for (int l = 0; l < 4; l++) {
                    int tx = j + dx[l], ty = k + dy[l];
                    if (tx >= 1 && tx <= n && ty >= 1 && ty <= n && grid1[tx][ty] != 'Y' && grid1[tx][ty] != 'Z') {
                        if (dist_cells[j][k] >= i && dist_cells[tx][ty] >= i) {
                            mf.add_edge(get_index(i - 1, tx, ty), get_index(i, j, k), INF);
                        }
                    }
                }
                mf.add_edge(get_index(i, j, k), target[get_index(0, j, k)], INF);
            }
        }
    }
    printf("%lld\n", mf.max_flow());
    return 0;
}
